const {vec} = NMath;
const {vertices, faces} = await IO.loadMesh("/assets/bunny.obj");

let pts = vertices.map(vertex => vec(...vertex));
const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    const scaled = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};
pts = normalizeVectors(pts);

const graph = Graph.knn(pts, 4, (x, y) => x.sub(y).length());
const sigma = 0.05;
const laplacian = graph.laplacian((i, j) => Math.exp(-i.vertex.sub(j.vertex).squareLength() / sigma));
const k = Math.min(256, pts.length);
const {eigenvalues, eigenvectors} = laplacian.eigen({maxFirst: false, k, maxIterations: 200, tolerance: 1e-3});
const eigenArrays = eigenvectors.map(eigenvector => eigenvector.toArray());

// Wave equation with Fix 1 (Smooth Initial Pulse) & Fix 2 (Modal Damping)
const wave = (j, t) => {
    const x = new Array(pts.length).fill(0);
    const dampingAlpha = 0.15;   // Overall damping rate (Fix 2)
    const smoothingTime = 0.03;  // Initial diffusion bandwidth to prevent ringing (Fix 1)

    eigenArrays.forEach((u, i) => {
        const lambda = eigenvalues[i];
        const omega = Math.sqrt(Math.max(0, lambda));

        // Fix 1: Exponential decay factor that suppresses high-frequency eigenmodes 
        // at t=0, turning the harsh delta spike into a smooth Gaussian bump.
        const smoothing = Math.exp(-lambda * smoothingTime);

        // Fix 2: Damping envelope so waves naturally fade out instead of forming standing noise
        const damping = Math.exp(- (dampingAlpha + 0.002 * lambda) * t);

        // Combined coefficient for the wave response
        const coefficient = smoothing * damping * Math.cos(omega * t) * u[j];

        for (let p = 0; p < x.length; p++) {
            x[p] += coefficient * u[p];
        }
    });
    return x;
};

const clamp = x => Math.min(1, Math.max(0, x));
const r = 10 / 4;
const toColors = values => {
    const max = values.reduce((value, x) => Math.max(value, x), Number.NEGATIVE_INFINITY);
    const min = values.reduce((value, x) => Math.min(value, x), Number.POSITIVE_INFINITY);
    const range = max - min;
    const isConstant = range < 0.05 * Math.max(Math.abs(max), Math.abs(min));
    return values.map(value => {
        const x = isConstant ? 0.5 : (value - min) / range;
        return [clamp(r * x), clamp(r * (x - 0.4)), clamp(5 * (x - 0.8))];
    });
};

const points = pts.map(point => point.toArray());
const triangles = faces.map(({vertices: indices}) => indices.map(index => points[index]));
const triangleColors = colors => faces.map(({vertices: indices}) => indices.map(vertexIndex => colors[vertexIndex]));

let source = 0;
let time = 0;
const initialColors = toColors(wave(source, time));
const pointPlot = IO.plotPointCloud(points, {color: initialColors});
const trianglePlot = IO.plotTriangleCloud(triangles, {color: triangleColors(initialColors)});

const updateWave = () => {
    const colors = toColors(wave(source, time));
    pointPlot.update(points, {color: colors});
    trianglePlot.update(triangles, {color: triangleColors(colors)});
    pointPlot.render();
    trianglePlot.render();
};

const ui = IO.UI(
    {type: "group", value: () => [
        {type: "canvas", value: () => pointPlot},
        {type: "canvas", value: () => trianglePlot},
    ]},
    {type: "slider", value: () => ({
        min: 0,
        max: 100,
        step: 0.05,
        value: 0,
        title: "Time:",
        onChange: value => { time = Number(value); updateWave(); },
    })},
    {type: "slider", value: () => ({
        min: 0,
        max: pts.length - 1,
        step: 1,
        value: 0,
        title: "Wave source vertex:",
        onChange: value => { source = Math.round(value); updateWave(); },
    })},
);
ui;
